import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.CXsxtpvq.js";const o="/asset-studio/shots/en/10-lab-empty.webp",m=JSON.parse('{"title":"Lab","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lab.md","filePath":"guide/lab.md"}'),n={name:"guide/lab.md"};function i(l,e,d,g,h,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h1><p>The <strong>Lab</strong> is for trying one prompt freely, outside the library. Vary the seed, or change one setting at a time, and compare the results side by side. Results are saved in <code>outputs/_lab/&lt;date&gt;/</code> and also appear in the gallery.</p><p><img src="'+o+'" alt="The lab"></p><h2 id="prompt-and-generation-settings" tabindex="-1">Prompt and generation settings <a class="header-anchor" href="#prompt-and-generation-settings" aria-label="Permalink to &quot;Prompt and generation settings&quot;">​</a></h2><ul><li><strong>Prompt</strong> / <strong>Negative prompt</strong>: write them yourself, with tag autocomplete. <strong>Check positive tags</strong> / <strong>Check negative tags</strong> point out tags Danbooru does not know.</li><li><strong>Generation settings</strong>: the same settings as in Jobs. <strong>Load a preset</strong> loads a saved generation preset; <strong>Save current settings as a preset</strong> creates one.</li></ul><p>You can also hand things over from elsewhere:</p><ul><li><strong>Open in Lab</strong> in the Jobs preview</li><li><strong>Open in Lab</strong> in the gallery&#39;s image view</li><li><strong>Open in Lab</strong> and <strong>Open tags in lab</strong> in the image tools</li></ul><p>The source is shown at the top when something was handed over.</p><h2 id="comparing-seeds" tabindex="-1">Comparing seeds <a class="header-anchor" href="#comparing-seeds" aria-label="Permalink to &quot;Comparing seeds&quot;">​</a></h2><p>Generates as many images as <strong>Seeds</strong>, each with its own seed. Shows how stable a prompt is.</p><h2 id="comparing-values" tabindex="-1">Comparing values <a class="header-anchor" href="#comparing-values" aria-label="Permalink to &quot;Comparing values&quot;">​</a></h2><p>Pick one setting under <strong>Value to vary</strong> and list the values under <strong>Values</strong>, separated by commas.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Example values</th></tr></thead><tbody><tr><td>CFG</td><td>3, 4.5, 6</td></tr><tr><td>Steps</td><td>20, 28, 36</td></tr><tr><td>Sampler · scheduler</td><td>leave empty for the whole list</td></tr><tr><td>CLIP skip (SDXL)</td><td>1, 2</td></tr><tr><td>LoRA strength</td><td>0.4, 0.7, 1.0</td></tr></tbody></table><p>You get seeds × values images (shown as, for example, &quot;2 seeds × 3 values = 6 images&quot;).</p><h2 id="comparing-results" tabindex="-1">Comparing results <a class="header-anchor" href="#comparing-results" aria-label="Permalink to &quot;Comparing results&quot;">​</a></h2><p>Choose two results as <strong>Reference</strong> and <strong>Result</strong>.</p><ul><li><strong>Side by side</strong>: the two next to each other.</li><li><strong>Slider</strong>: one over the other; drag the edge to see the difference.</li><li><strong>Swap reference and result</strong> and <strong>Load the result&#39;s settings</strong> (brings the settings of the one you like back into the form) are available.</li></ul>',17)])])}const c=t(n,[["render",i]]);export{m as __pageData,c as default};
